mapper.select:
SELECT p.stock_id AS stock_id, p.trade_date AS trade_date, p.open_price AS open_price, p.high_price AS high_price, p.low_price AS low_price, p.close_price AS close_price, p.volume AS volume, i.dif AS dif, i.dea AS dea, i.osc AS osc, i.k_value AS k_value, i.d_value AS d_value, i.j_value AS j_value FROM stock_daily_price p LEFT JOIN stock_daily_indicator i ON i.stock_id = p.stock_id AND i.trade_date = p.trade_date AND i.param_key = #{paramKey} AND i.is_warmup = 0 WHERE p.stock_id IN
#{id}
AND p.trade_date BETWEEN #{startDate} AND #{endDate} ORDER BY p.stock_id ASC, p.trade_date ASC
